-- Reward ids are md5 of a stable name, so re-running updates instead of duplicating.

-- The welcome gift is the cinnamon-roll reward (data/koala/rewards.json welcome_reward):
-- config.welcome.rewardId. Re-running sets it again and keeps every other setting.
insert into public.brands (slug, name, default_locale, time_zone, config)
values ('koala', 'Koala Coffee', 'el', 'Europe/Athens', jsonb_build_object('welcome', jsonb_build_object('rewardId', md5('koala:reward:cinnamon-roll')::uuid::text)))
on conflict (slug) do update set
  name = excluded.name,
  config = public.brands.config || jsonb_build_object(
    'welcome', coalesce(public.brands.config -> 'welcome', '{}'::jsonb) || jsonb_build_object('rewardId', md5('koala:reward:cinnamon-roll')::uuid::text));

